 18	        await context.WritePluginsAsync("*d.esm", "*a.esm", "*c.esm");
 19	
 20	        var diff = await DiffService.GetPluginsDiffAsync(context.Config);
 21	
 22	        Assert.Contains(diff, item => item.ChangeType == DiffChangeType.Removed && item.FileName == "b.esm");
 23	        Assert.Contains(diff, item => item.ChangeType == DiffChangeType.Inserted && item.FileName == "d.esm");
 24	    }
