301	        /// <list type="number">
302	        ///   <item>Items in the LCS whose absolute positions differ → candidate shifted (Moved).</item>
303	        ///   <item>Same-filename reconciliation: removed mod whose filename also appears in the new
304	        ///         set → Moved (swapped); performed before replacement detection.</item>
305	        ///   <item>Replacement detection: removed item at reference position R paired with the new
306	        ///         item at the corresponding LCS-aligned current position → Replaced.</item>
307	        ///   <item>Remaining new items classified as Added (beyond all surviving reference mods)
308	        ///         or Inserted (within the range of surviving reference mods).</item>
309	        ///   <item>Shifted LCS items grouped as dependent changes under their causal
310	        ///         insertion/deletion and removed from the top-level list.</item>
311	        /// </list>
312	        /// </remarks>
313	        internal static List<DiffLineModel> ClassifyChanges(
314	            IReadOnlyList<ModEntryModel> reference,
315	            IReadOnlyList<ModEntryModel> current,
316	            List<(int refIndex, int curIndex)> lcs)
317	        {
318	            // --- Step 0: Build fast lookup sets ---
319	            var lcsRefIndices = new HashSet<int>();
320	            var lcsCurIndices = new HashSet<int>();
321	            foreach (var (ri, ci) in lcs)
322	            {
323	                lcsRefIndices.Add(ri);
324	                lcsCurIndices.Add(ci);
325	            }
326	
327	            // Items in reference not in LCS → Removed candidates
328	            var removedMods = new List<ModEntryModel>();
329	            for (int i = 0; i < reference.Count; i++)
330	            {
331	                if (!lcsRefIndices.Contains(i))
332	                {
333	                    removedMods.Add(reference[i]);
334	                }
335	            }
336	
337	            // Items in current not in LCS → New candidates
338	            var newMods = new List<ModEntryModel>();
339	            for (int j = 0; j < current.Count; j++)
340	            {
341	                if (!lcsCurIndices.Contains(j))
342	                {
343	                    newMods.Add(current[j]);
344	                }
345	            }
346	
347	            // --- Step 1: LCS-shifted items (same relative order, different absolute position) ---
348	            // These are the "moved due to neighbour insertion/deletion" entries that will become
349	            // dependent changes. We track them but don't emit them as top-level entries yet.
350	            var lcsShifted = new List<(ModEntryModel mod, int refPos, int curPos)>();
351	            foreach (var (ri, ci) in lcs)
352	            {
353	                int refPos = reference[ri].LineNumber ?? (ri + 1);
354	                int curPos = current[ci].LineNumber ?? (ci + 1);
355	                if (refPos != curPos)
356	                {
357	                    lcsShifted.Add((reference[ri], refPos, curPos));
358	                }
359	            }
360	
361	            // --- Step 2: Same-filename reconciliation (Moved / swapped) ---
362	            var newByFilename = new Dictionary<string, ModEntryModel>(StringComparer.OrdinalIgnoreCase);
363	            foreach (var m in newMods)
364	            {
365	                newByFilename.TryAdd(m.FileName, m);
366	            }
367	
368	            var movedResults = new List<DiffLineModel>();
369	            var reconciledRemovedFilenames = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
370	            var reconciledNewMods = new HashSet<ModEntryModel>(ReferenceEqualityComparer.Instance);
371	
372	            foreach (var removed in removedMods)
373	            {
374	                if (newByFilename.TryGetValue(removed.FileName, out var matchingNew))
375	                {
376	                    // Same filename appeared in both removed and new → swapped/moved
377	                    string text = _localization.GetString("DiffDialog", "MovedText_Description",
378	                        removed.FileName,
379	                        removed.LineNumber ?? 0,
380	                        matchingNew.LineNumber ?? 0);
381	                    movedResults.Add(new DiffLineModel(
382	                        removed.FileName, text, DiffChangeType.Moved,
383	                        removed.LineNumber, matchingNew.LineNumber));
384	
385	                    reconciledRemovedFilenames.Add(removed.FileName);
386	                    reconciledNewMods.Add(matchingNew);
387	                }
388	            }
389	
390	            // Remove reconciled items from working sets
391	            var remainingRemoved = removedMods
392	                .Where(m => !reconciledRemovedFilenames.Contains(m.FileName))
393	                .ToList();
394	            var remainingNew = newMods
395	                .Where(m => !reconciledNewMods.Contains(m))
396	                .ToList();
397	
398	            // --- Step 3: Replacement detection (LCS-aligned position matching) ---
399	            // Build a map from current-list positions of new items for quick lookup
400	            var newByCurPos = new Dictionary<int, ModEntryModel>();
401	            foreach (var m in remainingNew)
402	            {
403	                int pos = m.LineNumber ?? 0;
404	                if (pos > 0 && !newByCurPos.ContainsKey(pos))
405	                {
406	                    newByCurPos[pos] = m;
407	                }
408	            }
409	
410	            // For each removed mod, determine its aligned current position:
411	            // Count how many reference items before it are in the LCS; the aligned position is
412	            // the (lcsRank + 1)-th surviving reference mod's current position neighbour.
413	            // Simpler direct approach: the expected current position of a removed mod at
414	            // reference index R is R + 1 minus the number of items removed before it
415	            // (i.e., other removed items at reference positions < R).
416	            var replacements = new Dictionary<ModEntryModel, ModEntryModel>(ReferenceEqualityComparer.Instance);
417	            var usedForReplacement = new HashSet<ModEntryModel>(ReferenceEqualityComparer.Instance);
418	
419	            // Sort removed mods by reference position for sequential processing
420	            var removedByRefPos = remainingRemoved
421	                .OrderBy(m => m.LineNumber ?? 0)
422	                .ToList();
423	
424	            int cumulativeDeletions = 0;
425	            foreach (var removed in removedByRefPos)
426	            {
427	                int refPos = removed.LineNumber ?? 0;
428	                // Aligned current position = reference position offset by cumulative prior deletions
429	                int alignedCurPos = refPos - cumulativeDeletions;
430	
431	                if (newByCurPos.TryGetValue(alignedCurPos, out var candidate)
432	                    && !usedForReplacement.Contains(candidate))
433	                {
434	                    replacements[removed] = candidate;
435	                    usedForReplacement.Add(candidate);
436	                }
437	                cumulativeDeletions++;
438	            }
439	
440	            // --- Step 4: Classify remaining new mods as Added or Inserted ---
441	            // maxSurvivingRefCurPos = highest current position of a mod that existed in reference
442	            // (either in LCS or as a moved/replacement pair)
